const CACHE_NAME="portfolio-storage-assets-v1";function isSupabaseStorageAsset(t){if("GET"!==t.method)return!1;const a=new URL(t.url);return a.hostname.endsWith(".supabase.co")&&a.pathname.startsWith("/storage/v1/object/public/")}async function cacheFirst(t){const a=await caches.open(CACHE_NAME),e=await a.match(t);if(e)return e;const s=await fetch(t);if(s.ok||"opaque"===s.type)try{await a.put(t,s.clone())}catch{}return s}globalThis.addEventListener("install",t=>{t.waitUntil(globalThis.skipWaiting())}),globalThis.addEventListener("activate",t=>{t.waitUntil(globalThis.clients.claim())}),globalThis.addEventListener("fetch",t=>{isSupabaseStorageAsset(t.request)&&t.respondWith(cacheFirst(t.request))});